    e=max((qo-ref(q,wq)).abs().max().item(),(ko-ref(k,wk)).abs().max().item())
    print(T,NC,ch,'err',e,'ctr nz',int((ctr!=0).sum()),flush=True)
  res={}
  res['os_il']=bp.harness_time(lambda q,k,wq,wk,qo,ko: K['os_il']((U,),(256,),q,k,wq,wk,qo,ko,nt,1e-6),[q,k,wq,wk],[qo,ko])
  for NC in (1,32):
