  ctr.zero_()
  for G in (148*8,148*16):
   for NC in (1,8,32):
    for ch in (1,2):
      GG=min(G,(U+ch-1)//ch); GG=max(GG,NC)
      res[f'ws G{G//148} N{NC} c{ch}']=bp.harness_time(lambda q,k,wq,wk,qo,ko,GG=GG,ch=ch,NC=NC: K['ws3']((GG,),(256,),q,k,wq,wk,qo,ko,nt,1e-6,ctr,ch,NC),[q,k,wq,wk],[qo,ko])
  print(T,'  '.join(f'{a}:{b:.2f}' for a,b in res.items()),flush=True)"}

{"note": "software-pipelined persistent: work-steal vs static stride", "script": "import torch, b200probe as bp
SRC = r'''
#define D 128
__device__ __forceinline__ void ld8(const float* p, float* v){
 asm volatile("ld.global.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];":"=f"(v[0]),"=f"(v[1]),"=f"(v[2]),"=f"(v[3]),"=f"(v[4]),"=f"(v[5]),"=f"(v[6]),"=f"(v[7]):"l"(p));}
__device__ __forceinline__ void st8(float* p, const float* v, unsigned long long pol){
