__device__ __forceinline__ unsigned long long pel(){unsigned long long p; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(p)); return p;}
struct Ctx{const float*q;const float*k;const float*wq;const float*wk;float*qo;float*ko;};
__device__ __forceinline__ void ldu(const Ctx& C,int u,float* xv){
 bool isk=u&1; int tile=u>>1; int r=threadIdx.x>>4, c=(threadIdx.x&15)*8;
 ld8((isk?C.k:C.q)+((size_t)tile*16+r)*D+c,xv);}
__device__ __forceinline__ void cmp(const Ctx& C,int u,const float* xv,float eps,unsigned long long p){
 bool isk=u&1; int tile=u>>1; int r=threadIdx.x>>4, c=(threadIdx.x&15)*8; int head=(tile%3)*16+r;
 float wv[8],yv[8]; ld8((isk?C.wk:C.wq)+head*D+c,wv);
 float s=0.f;
 #pragma unroll
 for(int i=0;i<8;i++) s=fmaf(xv[i],xv[i],s);
 s+=__shfl_xor_sync(0xffffffffu,s,8); s+=__shfl_xor_sync(0xffffffffu,s,4);
 s+=__shfl_xor_sync(0xffffffffu,s,2); s+=__shfl_xor_sync(0xffffffffu,s,1);
 float inv=rsqrtf(s*(1.0f/128)+eps);
 #pragma unroll
 for(int i=0;i<8;i++) yv[i]=(xv[i]*inv)*wv[i];
 st8((isk?C.ko:C.qo)+((size_t)tile*16+r)*D+c,yv,p);}
template<bool STEAL> __device__ void body(Ctx C,int n_tiles,float eps,unsigned* ctr){
 __shared__ int sidx[2];
 int U=2*n_tiles, G=gridDim.x, b=blockIdx.x; unsigned long long p=pel();
 // number of CTAs that do a stealing grab = those with second static unit valid
 int m=max(0,min(G,U-G)); int Lw=max(0,U-2*G); unsigned last=(unsigned)(Lw+m-1);
 int cur=b, nxt=G+b, buf=0;
 float xa[8],xb[8];
 if(cur<U) ldu(C,cur,xa);
 while(cur<U){
  if(nxt<U){
    if(threadIdx.x==0){ int v;
      if(STEAL){ unsigned o=atomicAdd(ctr,1u); if(o==last) atomicExch(ctr,0u); v=2*G+(int)o; } else v=nxt+G;
      sidx[buf]=v; }
    ldu(C,nxt,xb);
  }
  cmp(C,cur,xa,eps,p);
  if(nxt>=U) break;
